use super::*;
use std::time::Duration;
#[derive(Default)]struct Sink{chunks:Vec<Vec<u8>>,work:u64,bytes:u64,reject:Option<u64>,work_stop:Option<u64>,published:u64}
impl AdmissionSink for Sink{
 fn reserve(&mut self,w:u64,b:u64)->Result<(),()>{if self.work_stop.is_some_and(|x|self.work+w>x){return Err(())}self.work+=w;self.bytes+=b;Ok(())}
 fn check(&mut self)->Result<(),()>{Ok(())}
 fn publish(&mut self,i:u64,b:&[u8])->Result<(),()>{self.published+=1;if self.reject==Some(i){return Err(())}assert_eq!(i,self.chunks.len() as u64);self.chunks.push(b.to_vec());Ok(())}
}
fn limits(chunk:usize)->Limits{Limits{chunk_bytes:chunk,total_bytes:4_000_000,chunks:100_000,work:100_000_000}}
fn source<'a>(hash:&'a[u8;32],g:&'a[equations::Polynomial],a:Option<&'a continuation::Attempt>)->EncodingSource<'a>{EncodingSource{
 identity:capture_projection::SourceIdentity{public_sha256:hash,factor_sha256:hash,launch_sha256:hash,binding_sha256:hash,map_bytes:b"retained-map-fixture",map_ack:None,publication_attempted:true,map_published:false,pattern:Some(7)},signed:&[(3,4),(3,7)],target:Some((5,6)),failure:None,stop:None,diagnostic:Some("partial fixture"),cursor:(0,1,2),expansion:None,normalized:g,continuation:a,lifts:&[],coverage:None,exclusions:None,accepted:None,status:capture_projection::Status::Incomplete,deadline:Instant::now()+Duration::from_secs(30)}}
fn bytes(s:&Sink,a:&Attempt)->Vec<u8>{let mut v=s.chunks.concat();v.extend_from_slice(&a.pending);v}
fn encode_case(g:&[equations::Polynomial],a:Option<&continuation::Attempt>,lim:Limits,sink:&mut Sink)->Attempt{encode(&source(&[0x31;32],g,a),9,lim,sink)}
#[test]fn huge_nested_polynomial_is_byte_bounded_and_chunk_invariant(){let g=vec![vec![vec![],(0..10_000).collect()],vec![]];let mut a=Sink::default();let r=encode_case(&g,None,limits(127),&mut a);assert_eq!(r.result,Ok(()));assert!(r.complete);assert!(r.pending.is_empty());assert!(a.chunks.iter().all(|v|v.len()<=127));assert!(a.chunks.len()>500);assert_eq!(r.encoded_bytes,r.acknowledged_bytes);assert_eq!(r.work,a.work);assert_eq!(r.allocation_bytes,a.bytes);let mut b=Sink::default();let rb=encode_case(&g,None,limits(32768),&mut b);assert_eq!(rb.result,Ok(()));assert_eq!(bytes(&a,&r),bytes(&b,&rb));}
#[test]fn exact_generator_and_monomial_order_including_zero_are_preserved(){let g=vec![vec![],vec![vec![]],vec![vec![9,3],vec![4]]];let mut sink=Sink::default();let a=encode_case(&g,None,limits(19),&mut sink);assert!(a.complete);let all=bytes(&sink,&a);let mut expected=vec![5];expected.extend_from_slice(&3u64.to_le_bytes());for p in &g{expected.push(5);expected.extend_from_slice(&(p.len() as u64).to_le_bytes());for t in p{expected.push(5);expected.extend_from_slice(&(t.len() as u64).to_le_bytes());for &x in t{expected.push(2);expected.extend_from_slice(&(x as u64).to_le_bytes());}}}assert_eq!(all.windows(expected.len()).filter(|w|*w==expected).count(),1);}
#[test]fn caps_keep_exact_prefix_and_never_claim_completion(){let g=vec![vec![(0..100).collect()]];let mut full=Sink::default();let all=encode_case(&g,None,limits(64),&mut full);let expected=bytes(&full,&all);for bytes_cap in [0,10,63,64,500,1000]{let mut sink=Sink::default();let mut l=limits(64);l.total_bytes=bytes_cap;let a=encode_case(&g,None,l,&mut sink);assert_eq!(a.result,Err(Failure::Cap));assert!(!a.complete);assert!(a.pending.len()<=64);assert!(expected.starts_with(&bytes(&sink,&a)));assert!(a.encoded_bytes<=bytes_cap);}let mut sink=Sink::default();let mut l=limits(64);l.chunks=2;let a=encode_case(&g,None,l,&mut sink);assert_eq!(a.result,Err(Failure::Cap));assert_eq!(a.acknowledged_chunks,2);assert_eq!(a.pending.len(),64);assert!(expected.starts_with(&bytes(&sink,&a)));}
#[test]fn publication_refusal_retains_full_pending_chunk_without_retry(){let g=vec![vec![(0..100).collect()]];let mut sink=Sink{reject:Some(2),..Default::default()};let a=encode_case(&g,None,limits(64),&mut sink);assert_eq!(a.result,Err(Failure::Publish));assert_eq!(a.acknowledged_chunks,2);assert_eq!(a.acknowledged_bytes,128);assert_eq!(a.pending.len(),64);assert_eq!(sink.published,3);assert!(!a.complete);}
#[test]fn original_owner_refusal_preserves_prefix_and_reservation_totals(){let mut sink=Sink{work_stop:Some(1000),..Default::default()};let a=encode_case(&[],None,limits(64),&mut sink);assert_eq!(a.result,Err(Failure::Owner));assert_eq!(a.work,sink.work);assert_eq!(a.allocation_bytes,sink.bytes);assert!(!a.complete);assert_eq!(a.encoded_bytes,a.acknowledged_bytes+a.pending.len() as u64);}
#[test]fn expired_original_deadline_makes_no_allocations_or_publications(){let hash=[0;32];let mut v=source(&hash,&[],None);v.deadline=Instant::now();let mut sink=Sink::default();let a=encode(&v,0,limits(64),&mut sink);assert_eq!(a.result,Err(Failure::Deadline));assert_eq!(sink.bytes,0);assert_eq!(sink.published,0);assert_eq!(a.encoded_bytes,0);}
#[test]fn identity_and_absent_vs_empty_continuation_survive_encoding(){let mut a=Sink::default();let r=encode_case(&[],None,limits(128),&mut a);let v=bytes(&a,&r);let empty=continuation::Attempt{partitions:vec![],queue:vec![],active:None,outcome:continuation::Outcome::Unknown,failure:None,charge:equations::Charge::default()};let mut b=Sink::default();let r=encode_case(&[],Some(&empty),limits(128),&mut b);assert_ne!(v,bytes(&b,&r));let mut c=Sink::default();let r=encode(&source(&[0x32;32],&[],None),9,limits(128),&mut c);assert_ne!(v,bytes(&c,&r));}
#[test]fn emit_actual_rust_traversal_fixture(){
 let native=scheduler::Attempt{batches:vec![],result:Err(scheduler::Failure::Cap),complete:false,basis:vec![scheduler::Row{polynomial:vec![vec![],vec![2,4]],proof:vec![scheduler::ProofTerm{generator:0,multiplier:vec![1,7]}]}],pending:vec![scheduler::Task{kind:scheduler::Kind::Field(0,2),degree:3,serial:8}],active:None,current:scheduler::Row{polynomial:vec![vec![3]],proof:vec![]},charge:equations::Charge{work:9,bytes:17},completed:1,row_xors:2,symbolic_reducers:3,field_tasks:4,ordinary_tasks:5,last_degree:3};
 let node=scheduler::search::Node{parent:None,origins:vec![scheduler::search::Origin::Original(0)],equations:vec![vec![vec![2]]],decisions:vec![],status:scheduler::search::NodeStatus::Running,native_disposition:Some(scheduler::search::NativeDisposition::LocalCap),native:Some(native),candidate:vec![true,false],candidate_valid:None,children:[None,None],refutation_row:None};
 let search=scheduler::search::SearchAttempt{result:Err(scheduler::Failure::Cap),verdict:scheduler::search::Verdict::Unknown,nodes:vec![node],queue:vec![0],active:Some(0),witness_node:None,charge:equations::Charge::default()};
 let a=continuation::Attempt{partitions:vec![continuation::Partition{parent:None,prefix:vec![],equations:vec![vec![vec![2]]],status:continuation::Status::Running,search:Some(search),audit:None,children:vec![],exclusion_record:None}],queue:vec![0],active:Some(0),outcome:continuation::Outcome::Unknown,failure:Some(continuation::Failure::Cap),charge:equations::Charge::default()};
 let g=vec![vec![],vec![vec![],(0..10_000).collect()]];let mut sink=Sink::default();let r=encode_case(&g,Some(&a),limits(257),&mut sink);assert!(r.complete);let root=std::path::Path::new(env!("ENCODER_FIXTURE_DIR"));std::fs::create_dir_all(root).unwrap();std::fs::write(root.join("snapshot.bin"),bytes(&sink,&r)).unwrap();for(i,v)in sink.chunks.iter().enumerate(){std::fs::write(root.join(format!("chunk-{i:06}.bin")),v).unwrap();}std::fs::write(root.join("scope.txt"),"Actual compiled Rust encode and retained-type traversal; synthetic source identity and partial retained structs; no authenticated original owner, CaptureEmitter publication or semantic replay.\n").unwrap();
}

#[test]fn emit_row_replay_fixture(){
 struct Ledger;impl equations::Owner for Ledger{fn reserve(&mut self,_:equations::Charge)->Result<(),()>{Ok(())}fn check(&mut self)->Result<(),()>{Ok(())}}
 let g=vec![vec![vec![],vec![0],vec![1]],vec![vec![0,1]]];
 let l=continuation::Limits{partitions:64,work:100_000_000,bytes:100_000_000,search:scheduler::search::SearchLimits{nodes:32,native:scheduler::Limits{batch_rows:128,batch_ops:1024,batches:32,variables:16,generators:64,basis:64,tasks:1024,terms:256,proof:1024,degree:8,work:20_000_000,bytes:50_000_000}},audit:check::Limits{nodes:32,work:50_000_000,bytes:50_000_000,certificate:bridge::Limits{variables:16,generators:64,terms:256,degree:8,proof:1024,wire:65536,work:20_000_000,bytes:20_000_000},checker:bqi::Limits::software()}};
 let mut ledger=Ledger;let mut session=continuation::Session::new(2,&g,l,Instant::now()+Duration::from_secs(20),&mut ledger);let outcome=session.next();eprintln!("retained continuation outcome: {:?}",outcome);let a=session.into_attempt();
 assert!(!a.partitions.is_empty());for p in &a.partitions{if let Some(audit)=&p.audit{eprintln!("audit result: {:?}",audit.result);for c in &audit.certificates{eprintln!("certificate result: {:?}",c.result);if let Some(a)=&c.audit{eprintln!("checker result: {:?}",a.result);}}}}
 let mut sink=Sink::default();let encoded=encode_case(&g,Some(&a),limits(257),&mut sink);assert!(encoded.complete);let out=std::path::Path::new(env!("ROW_REPLAY_FIXTURE_DIR"));std::fs::create_dir_all(out).unwrap();std::fs::write(out.join("snapshot.bin"),bytes(&sink,&encoded)).unwrap();
 for(i,chunk)in sink.chunks.iter().enumerate(){std::fs::write(out.join(format!("chunk-{i:06}.bin")),chunk).unwrap();}
}
